import re
from playwright.sync_api import Page, expect

from tests.generated.pages.base_page import BasePage


class WikipediaHomePage(BasePage):
    """Generated by WebPilot.

    url_pattern: https://www.wikipedia.org/
    """

    def __init__(self, page: Page):
        super().__init__(page)

    def goto(self):
        self.page.goto("https://www.wikipedia.org/")

    def fill_search_wikipedia(self):
        # selector: confidence 0.99
        self.page.locator("input[id=\"searchInput\"]").fill("Software testing")
        # assertion(strong): Form value equals entered value
        expect(self.page.locator("input[id=\"searchInput\"]")).to_have_value("Software testing")

    def click_search_button(self):
        # selector: confidence 0.99
        self.page.get_by_role("button", name="Search").click()

    def assert_wikipedia_homepage_loads_successfully(self):
        # assertion(strong): URL is https://www.wikipedia.org/
        pass

    def assert_search_wikipedia(self):
        # assertion(strong): text selector is visible
        expect(self.page.get_by_text("Search Wikipedia")).to_be_visible()
        # assertion(medium): URL is https://www.wikipedia.org/

    def assert_page_url_contains_software_testing(self):
        # assertion(strong): URL contains "Software_testing"
        expect(self.page).to_have_url(re.compile("Software_testing"))
        # assertion(medium): URL is https://www.wikipedia.org/

    def assert_page_url_contains_talk(self):
        # assertion(strong): URL contains "Talk"
        expect(self.page).to_have_url(re.compile("Talk"))
        # assertion(medium): URL is https://www.wikipedia.org/
